"""Pinned bilingual retry-adapter chapter; distinguish source facts and bounded execution."""
import datetime,hashlib,json,re
from pathlib import Path
P=Path(__file__).resolve().parent;pack=json.loads((P/'backoff-source-pack-v1.json').read_text());units=pack['units'];runtime=json.loads((P/'backoff-confined-runtime-results-v1.json').read_text());compat=json.loads((P/'backoff-source-compatibility-results-v1.json').read_text());assert all(c['passes']==c['cases']for c in runtime['results']+compat['results']);claims=[];C='v4.3.0:';O='v4.1.3:'
def add(id,section,en,pt,refs,cases=(),consumers=()):
 assert re.findall(r'`([^`]+)`',en)==re.findall(r'`([^`]+)`',pt),id
 refs=[x if ':'in x else C+x for x in refs];assert all(x in units for x in refs);claims.append({'id':id,'section':section,'en':en,'pt-br':pt,'evidence_ids':refs,'runtime_case_ids':list(cases),'compiler_consumer_ids':list(consumers),'review_status':'AGENT_SOURCE_REVIEWED_NOT_OWNER_GOLD'})
add('purpose','Purpose / Propósito','The pinned `backoff` package composes retry operations with delay policies, context wrappers and optional notification. The policy interface supplies `NextBackOff` and `Reset`; the retry loop, timer and context have different responsibilities. A policy value alone does not establish an application retry, deadline or cancellation guarantee.','O pacote `backoff` fixado compõe operações de repetição com políticas de atraso, wrappers de contexto e notificação opcional. A interface da política fornece `NextBackOff` e `Reset`; o laço de repetição, o timer e o contexto possuem responsabilidades distintas. Um valor de política sozinho não estabelece garantia de repetição, prazo ou cancelamento de uma aplicação.',['BackOff','Retry','RetryNotifyWithTimer','Timer','BackOffContext'])
add('architecture','Architecture / Arquitetura','In the current cut, `Retry` delegates through `RetryNotify` and `RetryNotifyWithTimer` into generic `doRetryNotify`; `Operation.withEmptyData` adapts the no-data callback. The earlier `RetryNotifyWithTimer` contains the loop directly. The refactor changes where complete behavior evidence must be selected, even though the shared bounded observations agree.','No recorte atual, `Retry` delega por `RetryNotify` e `RetryNotifyWithTimer` até o auxiliar genérico `doRetryNotify`; `Operation.withEmptyData` adapta o callback sem dados. O `RetryNotifyWithTimer` anterior contém o laço diretamente. A refatoração muda onde a evidência completa de comportamento precisa ser selecionada, embora as observações limitadas compartilhadas coincidam.',['Retry','RetryNotify','RetryNotifyWithTimer','Operation.withEmptyData','doRetryNotify',O+'RetryNotifyWithTimer'])
add('configuration','Dependencies and configuration / Dependências e configuração','Both selected root packages use only Go standard-library imports. Their module directives change from `go 1.13` to `go 1.18` for `github.com/cenkalti/backoff/v4`. The executed context is existing Go1.27.4 Linux/ARM64 with CGO and package downloads disabled; no minimum-version or installed-distribution compatibility claim follows from those directives.','Os dois pacotes raiz selecionados usam apenas imports da biblioteca padrão Go. Suas diretivas de módulo mudam de `go 1.13` para `go 1.18` em `github.com/cenkalti/backoff/v4`. O contexto executado é o Go1.27.4 existente em Linux/ARM64, com CGO e downloads de pacotes desativados; dessas diretivas não decorre alegação de compatibilidade com versão mínima ou distribuição instalada.',['doRetryNotify','WithContext','ExponentialBackOff.NextBackOff'])
add('attempts','Attempts and notification / Tentativas e notificação','`WithMaxRetries` counts allowed calls through its wrapper, not total operation attempts. In the frozen failing-operation observations, a limit of 0 still allowed the initial operation once, while a limit of 2 produced three attempts, two notifications and two owned timer starts. These counts apply to the shown composition and do not establish a network retry policy.','`WithMaxRetries` conta chamadas permitidas por seu wrapper, não o total de tentativas da operação. Nas observações congeladas com operação que falha, um limite de 0 ainda permitiu a operação inicial uma vez, enquanto um limite de 2 produziu três tentativas, duas notificações e duas partidas do timer próprio. Essas contagens valem para a composição mostrada e não estabelecem uma política de repetição de rede.',['WithMaxRetries','backOffTries.NextBackOff','doRetryNotify'],['max-retries-zero','max-retries-two'])
add('initial-context','Context boundaries / Limites de contexto','With the valid owned policy, a context canceled before retry did not prevent the first operation. An immediate successful operation returned success. A failing operation returned `context.Canceled` when the context-backed policy stopped; a permanent failure instead returned its wrapped operation error because that check precedes the backoff/context stop path.','Com a política própria válida, um contexto cancelado antes da repetição não impediu a primeira operação. Uma operação imediatamente bem-sucedida retornou sucesso. Uma operação que falhou retornou `context.Canceled` quando a política apoiada no contexto parou; uma falha permanente retornou seu erro de operação encapsulado, pois essa verificação precede o caminho de parada da política e do contexto.',['doRetryNotify','WithContext','backOffContext.NextBackOff'],['canceled-success','canceled-error','canceled-permanent'])
add('context-wrappers','Context boundaries / Limites de contexto','`getContext` recognizes a context-backed policy and recursively unwraps `backOffTries`. Both wrapper orders returned the canceled context error in the selected observations. Separately, wrapping an existing direct context wrapper with `WithContext` replaces its context rather than preserving both cancellation conditions; the observed new live context allowed the underlying zero delay despite the old canceled context.','`getContext` reconhece uma política apoiada no contexto e desembrulha recursivamente `backOffTries`. As duas ordens de wrappers retornaram o erro de contexto cancelado nas observações selecionadas. Separadamente, envolver um wrapper direto de contexto existente com `WithContext` substitui seu contexto, em vez de preservar as duas condições de cancelamento; o novo contexto ativo observado permitiu o atraso zero subjacente apesar do contexto antigo cancelado.',['getContext','WithContext','backOffContext.NextBackOff','backOffTries.NextBackOff'],['tries-outside-context','context-outside-tries','context-rewrap'])
add('permanent','Errors and identity / Erros e identidade','The retry loop uses `errors.As` to find `*PermanentError` even through an owned outer wrapper, then returns its inner error. `Permanent(nil)` returns `nil`. Separately, `PermanentError.Is` recognizes the wrapper type regardless of the compared inner errors, while `Unwrap` exposes the inner error. These are distinct class-match and error-identity relationships.','O laço de repetição usa `errors.As` para encontrar `*PermanentError` mesmo através de um wrapper externo próprio, e então retorna seu erro interno. `Permanent(nil)` retorna `nil`. Separadamente, `PermanentError.Is` reconhece o tipo do wrapper independentemente dos erros internos comparados, enquanto `Unwrap` expõe o erro interno. São relações distintas de correspondência de classe e identidade de erro.',['doRetryNotify','Permanent','PermanentError.Is','PermanentError.Unwrap'],['permanent-direct','permanent-wrapped','permanent-nil','permanent-is-class','permanent-unwrap'])
add('notify','Attempts and notification / Tentativas e notificação','Notification occurs only after a failed non-permanent operation obtains a delay other than `Stop`, and before the timer starts. The owned order trace is reset, first operation, next delay, notification, timer start, second operation and timer stop. A final stop or permanent error produced no notification.','A notificação ocorre apenas depois que uma operação não permanente que falhou obtém um atraso diferente de `Stop`, e antes da partida do timer. O rastreamento próprio de ordem é reset, primeira operação, próximo atraso, notificação, partida do timer, segunda operação e parada do timer. Uma parada final ou um erro permanente não produziu notificação.',['doRetryNotify','Timer'],['notify-order','stop-error','permanent-direct'])
add('panic-cleanup','Errors and identity / Erros e identidade','The loop defers `Timer.Stop`. Owned panics from the operation, notification and timer-start callbacks propagated to the driver recovery while the owned timer stop count was one. This is bounded cleanup evidence, not a claim that the library catches callback panics, restores application state or provides crash recovery.','O laço adia `Timer.Stop`. Panics próprios dos callbacks de operação, notificação e partida do timer propagaram até a recuperação do driver, enquanto a contagem de parada do timer próprio foi um. Isso é evidência limitada de limpeza, não alegação de que a biblioteca captura panics de callbacks, restaura estado da aplicação ou fornece recuperação de falhas.',['doRetryNotify','Timer'],['operation-panic','notify-panic','timer-start-panic'])
add('stop-option','Stop sentinel and elapsed budget / Sentinela de parada e limite decorrido','`WithRetryStopDuration` assigns `ExponentialBackOff.Stop`; it does not set `MaxElapsedTime`. The policy can return that configured value after its elapsed-plus-next-delay check, while the retry loop compares against package `Stop`, whose value is -1. With a configured positive 5 ms stop value and an owned expired clock, the observed loop scheduled that value and made a second successful attempt. The same effect existed through the earlier public field; the new option is not a newly introduced runtime effect.','`WithRetryStopDuration` atribui `ExponentialBackOff.Stop`; não define `MaxElapsedTime`. A política pode retornar esse valor configurado após verificar tempo decorrido mais próximo atraso, enquanto o laço de repetição compara com `Stop` do pacote, cujo valor é -1. Com valor de parada positivo de 5 ms e relógio próprio expirado, o laço observado agendou esse valor e realizou uma segunda tentativa bem-sucedida. O mesmo efeito existia pelo campo público anterior; a nova opção não é um efeito de execução recém-introduzido.',['WithRetryStopDuration','ExponentialBackOff.NextBackOff','doRetryNotify',O+'ExponentialBackOff.NextBackOff',O+'RetryNotifyWithTimer'],['exp-custom-stop','custom-positive-stop-retry','positive-stop-option-retry'])
add('intervals','Stop sentinel and elapsed budget / Sentinela de parada e limite decorrido','The next-delay check includes both elapsed time and the proposed wait, so the owned policy could return `Stop` at elapsed time zero when its first delay exceeded the budget. A separately configured initial interval above the maximum interval produced 100 ms and then 50 ms with jitter output disabled. The selected code does not validate those caller settings or guarantee every proposed delay is within the configured maximum.','A verificação do próximo atraso inclui tanto o tempo decorrido quanto a espera proposta, de modo que a política própria pôde retornar `Stop` com tempo decorrido zero quando seu primeiro atraso excedia o limite. Um intervalo inicial configurado separadamente acima do intervalo máximo produziu 100 ms e depois 50 ms com a saída de jitter desativada. O código selecionado não valida essas configurações do chamador nem garante que todo atraso proposto esteja dentro do máximo configurado.',['ExponentialBackOff.NextBackOff','ExponentialBackOff.incrementCurrentInterval','ExponentialBackOff.Reset','getRandomValueFromInterval'],['exp-predicted-wait-cutoff','exp-initial-over-cap','exp-growth'])
add('data','Inputs and outputs / Entradas e saídas','The current generic loop returns the latest operation data even on its final error paths. Owned observations returned data 73 with the operation error, 91 with the inner permanent error and 17 with cancellation; success returned 42. Do not describe every error result as zero data, and do not infer useful application data from these synthetic values.','O laço genérico atual retorna os dados mais recentes da operação mesmo em seus caminhos finais de erro. As observações próprias retornaram dados 73 com o erro da operação, 91 com o erro permanente interno e 17 com cancelamento; o sucesso retornou 42. Não descreva todo resultado de erro como dados zerados, nem deduza dados úteis de aplicação desses valores sintéticos.',['OperationWithData','RetryNotifyWithTimerAndData','doRetryNotify'],['generic-final-error','generic-permanent','generic-cancel','generic-success'])
add('factory-type','Source compatibility / Compatibilidade de código','Adding variadic constructor options preserved the compiled zero-argument call, but changed function type assignability: an owned `func() *backoff.ExponentialBackOff` factory assignment compiled before and failed in the new cut. The variadic factory type, option call and generic data function compiled only in the current cut; the existing retry-with-timer function type compiled in both. This is six consumer shapes, not full API compatibility.','Adicionar opções variádicas ao construtor preservou a chamada compilada sem argumentos, mas mudou a atribuição entre tipos de função: uma atribuição própria de fábrica `func() *backoff.ExponentialBackOff` compilou antes e falhou no novo recorte. O tipo de fábrica variádica, a chamada com opção e a função genérica de dados compilaram apenas no recorte atual; o tipo existente da função de repetição com timer compilou nos dois. São seis formas de consumo, não compatibilidade completa da API.',['NewExponentialBackOff','ExponentialBackOffOpts',O+'NewExponentialBackOff','RetryNotifyWithTimer'],[],['zero-argument-call','zero-argument-factory-type','variadic-factory-type','option-call','generic-data-function','stable-retry-timer-type'])
add('options','Source compatibility / Compatibilidade de código','Constructor options run in order before `Reset`; the last observed initial-interval option won, and the owned clock was read once during construction. Supplying a nil clock option panicked in the bounded observation. The setter names do not imply configuration validation or a guaranteed valid clock.','As opções do construtor são executadas em ordem antes de `Reset`; a última opção observada de intervalo inicial prevaleceu, e o relógio próprio foi lido uma vez durante a construção. Fornecer uma opção de relógio nulo produziu panic na observação limitada. Os nomes dos setters não implicam validação de configuração nem garantia de relógio válido.',['NewExponentialBackOff','WithInitialInterval','WithClockProvider','ExponentialBackOff.Reset'],['constructor-options','constructor-option-order','nil-clock-option-panic'])
add('limits','Limitations / Limitações','Thirty shared frozen scenarios matched once per source cut, and eight current-only API scenarios matched in the current cut. Six compile-only consumer shapes were checked per cut. The retry observations used owned synchronous timer channels and clocks: no real sleeping, retry timer, ticker, network request or upstream test was used. No other operating system, race safety, arbitrary callback behavior or installed dependency identity was certified.','Trinta cenários congelados compartilhados coincidiram uma vez por recorte de código, e oito cenários de APIs apenas atuais coincidiram no recorte atual. Seis formas de consumo apenas compiladas foram verificadas por recorte. As observações de repetição usaram canais síncronos de timer e relógios próprios: nenhuma espera real, timer de repetição, ticker, requisição de rede ou teste externo foi usado. Nenhum outro sistema operacional, segurança contra condições de corrida, comportamento de callback arbitrário ou identidade de dependência instalada foi certificado.',['doRetryNotify','Timer','getContext'])
faqs=[('attempts','Does a retry limit of zero prevent the initial operation?','Um limite de repetição zero impede a operação inicial?','attempts'),('cancellation','Does prior cancellation always prevent the operation or override a permanent error?','O cancelamento anterior sempre impede a operação ou substitui um erro permanente?','initial-context'),('stop','Does the stop-duration option set an elapsed-time deadline?','A opção de duração de parada define um prazo de tempo decorrido?','stop-option'),('data','Must final error data be zero in the generic API?','Os dados finais de erro precisam ser zero na API genérica?','data'),('factory','Are zero-argument calls and zero-argument factory types equally compatible?','Chamadas sem argumentos e tipos de fábrica sem argumentos são igualmente compatíveis?','factory-type'),('notification','Is every failed attempt notified?','Toda tentativa que falha é notificada?','notify'),('error-identity','Does matching a permanent wrapper prove equal inner errors?','Corresponder a um wrapper permanente comprova erros internos iguais?','permanent')]
byid={c['id']:c for c in claims};faq=[{'id':id,'en_q':en,'pt-br_q':pt,'en_a':byid[c]['en'],'pt-br_a':byid[c]['pt-br'],'claim_id':c,'evidence_ids':byid[c]['evidence_ids']}for id,en,pt,c in faqs]
example='''package example

import (
    "errors"
    backoff "github.com/cenkalti/backoff/v4"
)

func Once() error {
    return backoff.Retry(func() error {
        return backoff.Permanent(errors.New("illustrative failure"))
    }, &backoff.StopBackOff{})
}'''
command='go doc github.com/cenkalti/backoff/v4.RetryNotifyWithTimer'
diagram='''flowchart LR
    A[Retry] --> B[RetryNotify]
    B --> C[RetryNotifyWithTimer]
    C --> D[Operation.withEmptyData]
    C --> E[doRetryNotify]
    E --> F[getContext]
    E --> G[BackOff.Reset / NextBackOff]
    E --> H[Notify / Timer]'''
out=P/'backoff-chapter-candidates-v1';out.mkdir(exist_ok=False);files={}
for lang in ['en','pt-br']:
 lines=['# '+('Retry boundaries, context and stop values'if lang=='en'else'Limites da repetição, contexto e valores de parada'),'','Research candidate; not owner-approved, training gold or published.'if lang=='en'else'Candidato de pesquisa; sem aprovação do proprietário, gold de treinamento ou publicação.','','Revisions: `6b0e4ad0cd65431b217393bff47d1dff727b264b` → `720b78985a65c0452fd37bb155c7cac4157a7c45`.','']
 for section in dict.fromkeys(c['section']for c in claims):
  lines+=['## '+section.split(' / ')[0 if lang=='en'else 1],'']
  for c in claims:
   if c['section']==section:lines+=[c[lang]+' '+' '.join('[source:'+x+']'for x in c['evidence_ids'])+(' [runtime:'+','.join(c['runtime_case_ids'])+']'if c['runtime_case_ids']else'')+(' [compiler:'+','.join(c['compiler_consumer_ids'])+']'if c['compiler_consumer_ids']else''),'']
 lines+=['## '+('Illustrative example and command'if lang=='en'else'Exemplo e comando ilustrativos'),'','Illustrative and unexecuted; no output or installation success is claimed.'if lang=='en'else'Ilustrativos e não executados; nenhuma saída ou instalação bem-sucedida é afirmada.','','```go',example,'```','','```sh',command,'```','','[source:'+C+'Retry] [source:'+C+'Permanent] [source:'+C+'StopBackOff.NextBackOff]','','## '+('Source map'if lang=='en'else'Mapa do código'),'','| File | '+('Responsibility'if lang=='en'else'Responsabilidade')+' |','|---|---|','| `retry.go` | '+('Operation, permanent-error checks, generic loop'if lang=='en'else'Operação, verificações de erro permanente, laço genérico')+' |','| `context.go` | '+('Context replacement and extraction'if lang=='en'else'Substituição e extração de contexto')+' |','| `tries.go` | '+('Retry-count wrapper'if lang=='en'else'Wrapper de contagem de repetição')+' |','| `exponential.go` | '+('Intervals, clock and configured stop value'if lang=='en'else'Intervalos, relógio e valor de parada configurado')+' |','| `timer.go` | '+('Timer interface and default implementation'if lang=='en'else'Interface do timer e implementação padrão')+' |','','## '+('Written relationships'if lang=='en'else'Relações escritas'),'','```mermaid',diagram,'```','','[source:'+C+'Retry] [source:'+C+'RetryNotify] [source:'+C+'RetryNotifyWithTimer] [source:'+C+'doRetryNotify]','','## FAQ','']
 for f in faq:lines+=['### '+f[lang+'_q'],'',f[lang+'_a']+' '+' '.join('[source:'+x+']'for x in f['evidence_ids']),'']
 lines+=['## '+('Evidence and license'if lang=='en'else'Evidência e licença'),'','[Runtime receipt](../backoff-confined-runtime-results-v1.json); [consumer compilation receipt](../backoff-source-compatibility-results-v1.json).','']
 for id in sorted(set(x for c in claims for x in c['evidence_ids'])|{C+'StopBackOff.NextBackOff'}):
  u=units[id];url='https://github.com/cenkalti/backoff/blob/'+u['revision']+'/'+u['source_path']+'#L'+str(u['first_line'])+'-L'+str(u['last_line']);lines+=['- [source:'+id+'] ['+u['source_path']+':'+str(u['first_line'])+'–'+str(u['last_line'])+']('+url+'); SHA-256 `'+u['source_sha256']+'`.']
